spec.expr:
topk(200,
max by (test_id, vcs_repository_name, server_version) (
  last_over_time(cae_v16_test_duration_seconds{vcs_repository_name=~"$repository", server_version=~"$server_version", vcs_repository_ref_name=~"$branch"}[$recent])
)
unless
max by (test_id, vcs_repository_name, server_version) (
  last_over_time(cae_v16_test_duration_seconds{vcs_repository_name=~"$repository", server_version=~"$server_version", vcs_repository_ref_name=~"$branch"}[$baseline] offset $recent)
)
)

count by (vcs_repository_name) (
  max by (test_id, vcs_repository_name, server_version) (
    last_over_time(cae_v16_test_duration_seconds{vcs_repository_name=~"$repository", server_version=~"$server_version", vcs_repository_ref_name=~"$branch"}[$baseline] offset $recent)
  )
  unless
  max by (test_id, vcs_repository_name, server_version) (
    last_over_time(cae_v16_test_duration_seconds{vcs_repository_name=~"$repository", server_version=~"$server_version", vcs_repository_ref_name=~"$branch"}[$recent])
  )
)

topk(20,
  max by (test_id, vcs_repository_name) (
    quantile_over_time(0.5,
      cae_v16_test_duration_seconds{vcs_repository_name=~"$repository", server_version=~"$server_version", vcs_repository_ref_name=~"$branch"}[$recent]
    )
  )
)

topk(20,
  max by (test_id, vcs_repository_name) (
      max by (test_id, vcs_repository_name, server_version) (
        quantile_over_time(0.5,
          cae_v16_test_duration_seconds{vcs_repository_name=~"$repository", server_version=~"$server_version", vcs_repository_ref_name=~"$branch"}[$recent]
        )
      )
    -
      max by (test_id, vcs_repository_name, server_version) (
        quantile_over_time(0.5,
          cae_v16_test_duration_seconds{vcs_repository_name=~"$repository", server_version=~"$server_version", vcs_repository_ref_name=~"$branch"}[$baseline] offset $recent
        )
      )
  )
)

topk(20,
  max by (test_id, vcs_repository_name) (
    (
      max by (test_id, vcs_repository_name, server_version) (quantile_over_time(0.5, cae_v16_test_duration_seconds{vcs_repository_name=~"$repository", server_version=~"$server_version", vcs_repository_ref_name=~"$branch"}[$baseline] offset $recent))
      -
      max by (test_id, vcs_repository_name, server_version) (quantile_over_time(0.5, cae_v16_test_duration_seconds{vcs_repository_name=~"$repository", server_version=~"$server_version", vcs_repository_ref_name=~"$branch"}[$recent]))
    ) > 0
  )
)
